import{d as v,C as d,o as S,c as V,a3 as l,E as e,j as a,a as t}from"./chunks/framework.D4-ViStF.js";const I=JSON.parse('{"title":"庄子·天道","description":"以天地为宗为上无为下有为、本末五末到轮扁斫轮，理解庄子以天道为标准的帝道圣道与人道。","frontmatter":{"title":"庄子·天道","description":"以天地为宗为上无为下有为、本末五末到轮扁斫轮，理解庄子以天道为标准的帝道圣道与人道。","category":"guide","aliases":["天道","庄子天道","zhuangzi chapter 13"],"source":["《庄子·天道》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-13.md","filePath":"daoism/zhuang-zi/chapter-13.md","lastUpdated":1788516578000}'),N={name:"daoism/zhuang-zi/chapter-13.md"},B=v({...N,setup(A){const o=[{id:"tiandao",sentences:[["天道运而无所积，故万物成；帝道运而无所积，故天下归；圣道运而无所积，故海内服。明于天，通于圣，六通四辟于帝王之德者，其自为也，昧然无不静者矣。"],["圣人之静也，非曰静也善，故静也。万物无足以挠心者，故静也。水静则明烛须眉，平中准，大匠取法焉。水静犹明，而况精神！圣人之心静乎！天地之鉴也，万物之镜也。"],["夫",{text:"虚静恬淡寂漠无为",glossary:"xujing"},"者，天地之平而道德之至也。故帝王圣人休焉。休则虚，虚则实，实则伦矣。虚则静，静则动，动则得矣。静则无为，无为也，则任事者责矣。无为则俞俞。俞俞者，忧患不能处，年寿长矣。"],["夫虚静恬淡寂漠无为者，万物之本也。明此以南乡，尧之为君也；明此以北面，舜之为臣也。以此处上，帝王天子之德也；以此处下，玄圣素王之道也。以此退居而闲游，江海山林之士服；以此进为而抚世，则功大名显而天下一也。"],["静而圣，动而王，无为也而尊，朴素而天下莫能与之争美。夫明白于天地之德者，此之谓大本大宗，与天和者也。所以均调天下，与人和者也。与人和者，谓之人乐；与天和者，谓之天乐。"],['庄子曰："吾师乎，吾师乎！赍万物而不为戾；泽及万世而不为仁；长于上古而不为寿；覆载天地、刻雕众形而不为巧。"此之谓天乐。'],["故曰：知天乐者，其生也天行，其死也物化。静而与阴同德，动而与阳同波。故知天乐者，无天怨，无人非，无物累，无鬼责。故曰：其动也天，其静也地，一心定而王天下；其鬼不祟，其魂不疲，一心定而万物服。言以虚静推于天地，通于万物，此之谓天乐。天乐者，圣人之心以畜天下也。"]]}],p=[{id:"xujing",term:"虚静恬淡寂漠无为",pinyin:"xū jìng tián dàn jì mò wú wéi",meaning:"五个并列：虚·静·恬淡·寂漠·无为。《天道》最重要的复合概念。天地之平·道德之至·万物之本。"}],m=[{id:"wuwei",sentences:[["夫帝王之德，以天地为宗，以道德为主，以无为为常。",{text:"无为也，则用天下而有余；有为也，则为天下用而不足",glossary:"yongtianxia"},"。故古之人贵夫无为也。"],["上无为也，下亦无为也，是下与上同德。下与上同德则不臣。下有为也，上亦有为也，是上与下同道。上与下同道则不主。"],["上必无为而用下，下必有为为天下用。此不易之道也。"]]}],h=[{id:"yongtianxia",term:"无为则用天下而有余",pinyin:"wú wéi zé yòng tiān xià ér yǒu yú",meaning:"无为，则驾驭天下，绰绰有余；有为，则被天下驱使，疲惫不足。「用天下」与「为天下用」——两个字的顺序，完全不同。"}],g=[{id:"wumo",sentences:[["本在于上，末在于下；要在于主，详在于臣。"],["三军五兵之运，德之末也；赏罚利害，五刑之辟，教之末也；礼法度数，刑名比详，治之末也；钟鼓之音，羽旄之容，乐之末也；哭泣衰絰，隆杀之服，哀之末也。"],["此五末者，须精神之运，心术之动，然后从之者也。末学者，古人有之，而非所以先也。"],["君先而臣从，父先而子从，兄先而弟从，长先而少从，男先而女从，夫先而妇从。夫尊卑先后，天地之行也，故圣人取象焉。天尊地卑，神明之位也；春夏先，秋冬后，四时之序也；万物化作，萌区有状，盛衰之杀，变化之流也。"],["夫天地至神矣，而有尊卑先后之序，而况人道乎！宗庙尚亲，朝廷尚尊，乡党尚齿，行事尚贤，大道之序也。语道而非其序者，非其道也。语道而非其道者，安取道哉！"]]}],y=[],b=[{id:"jiuceng",sentences:[["是故古之明大道者，先明天而道德次之，道德已明而仁义次之，仁义已明而分守次之，分守已明而形名次之，形名已明而因任次之，因任已明而原省次之，原省已明而是非次之，是非已明而赏罚次之，赏罚已明而愚知处宜，贵贱履位，仁贤不肖袭情。必分其能，必由其名。"],['以此事上，以此畜下，以此治物，以此修身，知谋不用，必归其天。此之谓大平，治之至也。故书曰："有形有名。"形名者，古人有之，而非所以先也。'],["古之语大道者，五变而形名可举，九变而赏罚可言也。",{text:"骤而语形名，不知其本也",glossary:"zhouer"},"；骤而语赏罚，不知其始也。倒道而言，迕道而说者，人之所治也，安能治人！"],["骤而语形名赏罚，此有知治之具，非知治之道。可用于天下，不足以用天下。此之谓辩士，一曲之人也。礼法数度，形名比详，古人有之。此下之所以事上，非上之所以畜下也。"]]}],u=[{id:"zhouer",term:"骤而语形名，不知其本也",pinyin:"zhòu ér yǔ xíng míng，bù zhī qí běn yě",meaning:"骤：急速、突然。跳过前面层级，直接谈形名——不知道根本。有知治之具，非知治之道。"}],x=[{id:"yaoshun",sentences:[['昔者舜问于尧曰："天王之用心何如？"尧曰："吾不敖无告，不废穷民，苦死者，嘉孺子而哀妇人，此吾所以用心已。"'],['舜曰："美则美矣，而未大也。"尧曰："然则何如？"舜曰："',{text:"天德而出宁",glossary:"tiande"},'，日月照而四时行，若昼夜之有经，云行而雨施矣！"'],['尧曰："',{text:"胶胶扰扰乎",glossary:"jiaojiao"},'！子，天之合也；我，人之合也。"'],["夫天地者，古之所大也，而黄帝、尧、舜之所共美也。故古之王天下者，奚为哉？天地而已矣！"]]}],c=[{id:"tiande",term:"天德而出宁",pinyin:"tiān dé ér chū níng",meaning:"天的德性自然流出安宁。不是主动去安宁百姓，而是：天德自然流出，安宁自来。"},{id:"jiaojiao",term:"胶胶扰扰乎",pinyin:"jiāo jiāo rǎo rǎo hū",meaning:"胶胶扰扰：纷扰忙碌的样子。尧听了舜的话，突然意识到自己的「用心」——是纷扰忙碌的，是执着于「用心」的。"}],f=[{id:"renyi",sentences:[['孔子西藏书于周室，子路谋曰："由闻周之征藏史有老聃者，免而归居，夫子欲藏书，则试往因焉。"孔子曰："善。"往见老聃，而老聃不许，于是繙十二经以说。'],['老聃中其说，曰："大谩，愿闻其要。"孔子曰："要在仁义。"老聃曰："请问：仁义，人之性邪？"孔子曰："然，君子不仁则不成，不义则不生。仁义，真人之性也，又将奚为矣？"'],['老聃曰："请问：何谓仁义？"孔子曰："中心物恺，兼爱无私，此仁义之情也。"'],['老聃曰："意，几乎后言！夫',{text:"兼爱，不亦迂夫",glossary:"jianai"},"！无私焉，乃私也。夫子若欲使天下无失其牧乎？则天地固有常矣，日月固有明矣，星辰固有列矣，禽兽固有群矣，树木固有立矣。"],["夫子亦",{text:"放德而行",glossary:"fangde"},'，遁遁而趋，已至矣！又何偈偈乎揭仁义，若击鼓而求亡子焉！意，夫子乱人之性也。"']]}],k=[{id:"jianai",term:"兼爱，不亦迂夫",pinyin:"jiān ài，bù yì yū fū",meaning:"兼爱，不也太迂腐了吗！把「爱」变成了一个需要努力达到的目标——真正的爱，是本然的，不需要「兼」。"},{id:"fangde",term:"放德而行",pinyin:"fàng dé ér xíng",meaning:"放：依循、顺应。顺应德性而行。不是主动去推行仁义，而是顺应本然的德性，自然而行。"}],z=[{id:"shichengqi",sentences:[['士成绮见老子而问曰："吾闻夫子圣人也。吾固不辞远道而来愿见，百舍重趼而不敢息。今吾观子，非圣人也。鼠壤有余蔬而弃妹，不仁也！生熟不尽于前，而积敛无崖。"老子漠然不应。'],['士成绮明日复见，曰："昔者吾有剌于子，今吾心正郤矣，何故也？"老子曰："夫巧知神圣之人，吾自以为脱焉。昔者子呼我牛也而谓之牛；呼我马也而谓之马。苟有其实，人与之名而弗受，再受其殃。',{text:"吾服也恒服，吾非以服有服",glossary:"wuful"},'。"'],['士成绮雁行避影，履行遂进，而问修身若何。老子曰："而容崖然，而目冲然，而颡頯然，而口阚然，而状义然。似系马而止也，动而持，发也机，察而审，知巧而睹于泰，凡以为不信。',{text:"边竟有人焉，其名为窃",glossary:"bianjing"},'。"']]}],P=[{id:"wuful",term:"吾服也恒服，吾非以服有服",pinyin:"wú fú yě héng fú，wú fēi yǐ fú yǒu fú",meaning:"我一贯顺服，我不是因为（你的批评）才顺服的。本然的顺服，不是有为的顺服。"},{id:"bianjing",term:"边竟有人焉，其名为窃",pinyin:"biān jìng yǒu rén yān，qí míng wéi qiè",meaning:"边竟：通「边境」，边界之处（不内不外的状态）。边界上有这样的人，他的名字叫做「窃」——用外在姿态来偷取道，不是真正的修道。"}],q=[{id:"zhiren",sentences:[['老子曰："夫道，于大不终，于小不遗，故万物备。广广乎其无不容也，渊渊乎其不可测也。',{text:"形德仁义，神之末也",glossary:"xingde"},"，非至人孰能定之！"],["夫至人有世，不亦大乎，而不足以为之累；天下奋柄而不与之偕；审乎无假而不与利迁；极物之真，能守其本。故",{text:"外天地，遗万物",glossary:"waitiandi"},"，而神未尝有所困也。"],['通乎道，合乎德，退仁义，宾礼乐，至人之心有所定矣！"']]}],w=[{id:"xingde",term:"形德仁义，神之末也",pinyin:"xíng dé rén yì，shén zhī mò yě",meaning:"形·德·仁义，都是精神（神）的末节。至人从精神（本）出发，精神安定，则形·德·仁义自然安定。"},{id:"waitiandi",term:"外天地，遗万物",pinyin:"wài tiān dì，yí wàn wù",meaning:"不执着于天地，放下万物——精神从未困扰。与《天地》「忘乎物·忘乎天·忘己·入于天」呼应。"}],j=[{id:"zhizhe",sentences:[["世之所贵道者，书也。书不过语，语有贵也。语之所贵者，意也，意有所随。意之所随者，不可以言传也，而世因贵言传书。世虽贵之，我犹不足贵也，为其贵非其贵也。"],["故视而可见者，形与色也；听而可闻者，名与声也。悲夫！世人以形色名声为足以得彼之情。"],["夫形色名声，果不足以得彼之情，则",{text:"知者不言，言者不知",glossary:"zhizhe"},"，而世岂识之哉！"]]}],T=[{id:"zhizhe",term:"知者不言，言者不知",pinyin:"zhī zhě bù yán，yán zhě bù zhī",meaning:"真正知道道的人，不说——因为道，不可以言传；说的人，不知道——因为能说出来的，都是「意」以下的层面。与《老子》「知者不博，博者不知」呼应。"}],G=[{id:"lunbian",sentences:[['桓公读书于堂上，轮扁斫轮于堂下，释椎凿而上，问桓公曰："敢问：公之所读者，何言邪？"公曰："圣人之言也。"曰："圣人在乎？"公曰："已死矣。"曰："然则君之所读者，古人之',{text:"糟粕",glossary:"zaopo"},'已夫！"'],['桓公曰："寡人读书，轮人安得议乎！有说则可，无说则死！"'],['轮扁曰："臣也以臣之事观之。斫轮，徐则甘而不固，疾则苦而不入，不徐不疾，得之于手而应于心，口不能言，有数存乎其间。臣不能以喻臣之子，臣之子亦不能受之于臣，是以行年七十而老斫轮。'],['古之人与其不可传也死矣，然则君之所读者，古人之糟粕已夫！"']]}],C=[{id:"zaopo",term:"糟粕",pinyin:"zāo pò",meaning:"酿酒剩下的渣滓，比喻精华已逝，只剩渣滓。圣人的言论，是道的「糟粕」——精华（道），随圣人而去，留下的文字，是渣滓。"}];return(R,n)=>{const D=d("DaoReadingPrelude"),i=d("DaoTextReading"),s=d("DaoKeywordCards"),r=d("DaoLineGuide");return S(),V("div",null,[n[0]||(n[0]=l('<h1 id="庄子·天道" tabindex="-1">庄子·天道 <a class="header-anchor" href="#庄子·天道" aria-label="Permalink to &quot;庄子·天道&quot;">​</a></h1><h2 id="篇名释义" tabindex="-1">篇名释义 <a class="header-anchor" href="#篇名释义" aria-label="Permalink to &quot;篇名释义&quot;">​</a></h2><blockquote><p><strong>《天道》承接《天地》——《天地》建立了层级：技·事·义·德·道·天；《天道》深化了核心：虚静无为，是天道·帝道·圣道的共同根基。</strong></p><p>篇名「天道」——不是说天道本身，而是说：以天道为标准，来理解帝道·圣道·人道。</p><p>全篇主轴只有一个：</p><blockquote><p><strong>虚静无为，是本；一切有为（仁义·礼法·形名·赏罚），是末。</strong></p></blockquote></blockquote>',3)),e(D,{title:"从虚静无为到轮扁斫轮，以天道为标准的帝道圣道人道",summary:"《天道》以「天道运而无所积」开篇，经虚静恬淡寂漠无为（万物之本）、上无为下有为（不易之道）、本末五末、明大道九层序列，到尧舜问答、孔子见老聃、士成绮见老子，最后以知者不言、轮扁斫轮收束——虚静无为是本，一切有为是末；道，不可以言传。",points:[{label:"先看",text:"顺着虚静天乐→上无为下有为→五末→九层→尧舜→老聃→士成绮→知者不言→轮扁这条线走一遍。"},{label:"再问",text:"「上必无为而用下」——今天还适用吗？"},{label:"最后",text:"轮扁的「数」——那个得之于手而应于心、无法言传的东西，你有吗？"}],hint:"这是外篇结构最完整的一篇之一。读的时候可以不断回看《天地》——两篇是同一套层级的两个展开。"}),n[1]||(n[1]=a("h2",{id:"一、天道虚静论·天乐",tabindex:"-1"},[t("一、天道虚静论·天乐 "),a("a",{class:"header-anchor",href:"#一、天道虚静论·天乐","aria-label":'Permalink to "一、天道虚静论·天乐"'},"​")],-1)),n[2]||(n[2]=a("h3",{id:"原文",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:o,glossary:p,"default-mode":"classic","aria-label":"天道·天道虚静论 原文"}),n[3]||(n[3]=a("h3",{id:"生僻字词",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"六通四辟",pinyin:["liù","tōng","sì","pì"],meaning:"六通：通达六合（上下四方）；四辟：开辟四方。通达天地四方，无所不达。"},{term:"明烛须眉",pinyin:["míng","zhú","xū","méi"],meaning:"烛：照亮。清晰地照出眉毛胡须（比喻极度清澈）。"},{term:"平中准",pinyin:["píng","zhōng","zhǔn"],meaning:"准：水准仪。水面平静，可以作为水准仪的标准。"},{term:"大匠取法焉",pinyin:["dà","jiàng"],meaning:"大匠：技艺高超的工匠。大工匠以此为法则。"},{term:"任事者责矣",pinyin:["zé"],meaning:"责：责任、职责。担任事务的人，各有其责任（自然各尽其职）。"},{term:"无为则俞俞",pinyin:["yú","yú"],meaning:"俞俞：安适自得、悠然自在的样子。无为则悠然自在。"},{term:"玄圣素王",pinyin:["xuán","shèng","sù","wáng"],meaning:"玄圣：深远的圣人；素王：没有王位但有王德的人。"},{term:"大本大宗",pinyin:["dà","běn","dà","zōng"],meaning:"最根本的根本，最根源的根源。"},{term:"以畜天下也",pinyin:["xù"],meaning:"畜：养育、蓄养。用来养育天下。"}]}),n[4]||(n[4]=a("h3",{id:"核心句引读",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"天道运而无所积——运行，但不积滞",subtitle:"「无所积」，是原因；万物成·天下归·海内服，是结果。",lines:[{text:"天道运而无所积，故万物成；帝道运而无所积，故天下归；圣道运而无所积，故海内服。",tone:"三道无积",guide:"《天道》开篇，三句并列——天道·帝道·圣道——三者，共同的特征只有一个：「运而无所积」——运行，但不积滞。「运」——运行，流动，不停止；「无所积」——不在任何地方积滞，不执着于任何地方。三者，因为「运而无所积」，所以：万物成·天下归·海内服。这三个结果，都是自然的——不是主动去「成万物」，而是万物自然成。「无所积」，是原因——万物成·天下归·海内服，是结果。为什么「无所积」会带来这些结果？因为「积」，是阻碍——天道一旦积滞，万物就无法流通。「运而无所积」——是《天道》对「道」最精准的描述：道，永远在运行——道，永远不积滞——这，就是天道的本质。"},{text:"圣人之静也，非曰静也善，故静也。万物无足以挠心者，故静也。",tone:"圣人之静",guide:"这两句，是《天道》对「静」最重要的定义——圣人之静，非曰静也善，故静也（圣人的静，不是因为「静是好的」，所以才静）——万物无足以挠心者，故静也（而是：万物，没有足以扰乱心的东西，所以静）。两句，区分了两种「静」：第一种静——主动追求的静（认为静是好的，所以努力让自己静——这，是有为的静——是把静当成目标的静——这种静，不是真正的静，因为它有执着）；第二种静——自然流出的静（万物，无足以挠心——不是强制不被打扰，而是：本来就没有什么能打扰——这，是无为的静——是本然的静——这，才是圣人之静）。很多人追求「静」——冥想·断网·闭关——但这些，都是「非曰静也善，故静也」——真正的静，是：万物无足以挠心——不是不接触万物，而是：接触了，但无足以挠心。"},{text:"夫虚静恬淡寂漠无为者，万物之本也。",tone:"万物之本",guide:"虚静恬淡寂漠无为——五个词，并列——虚：虚空；静：安静；恬淡：安静淡泊；寂漠：寂静空寂；无为：不主动作为——天地之平而道德之至也（这，是天地的准则，道德的极致）。故帝王圣人休焉——帝王圣人，在虚静无为中，找到了根本——这，是他们的归宿。休则虚，虚则实，实则伦矣（虚空，反而充实——因为虚空，才能容纳——满的东西，无法再容纳）；虚则静，静则动，动则得矣（静，是动的根基——从静出发的动，才是真正的动）。夫虚静恬淡寂漠无为者，万物之本也——这一句，是第1段的核心命题：虚静无为，是万物的根本——万物，从虚静无为中来——万物，回到虚静无为中去。"},{text:"庄子曰：吾师乎，吾师乎！赍万物而不为戾；泽及万世而不为仁；长于上古而不为寿；覆载天地、刻雕众形而不为巧。此之谓天乐。",tone:"天乐",guide:"庄子，直接出现——「吾师乎，吾师乎！」——我的老师啊！这个「吾师」，不是具体的人——而是：道——庄子，称道为「吾师」。四个「不为」：赍万物而不为戾（给予万物而不以为有罪过），泽及万世而不为仁（恩泽万世而不以为是在行仁），长于上古而不为寿（比上古还长久而不以为是长寿），覆载天地、刻雕众形而不为巧（创造了一切，而不以为是技巧）。四个「不为」，是道的最高特征：道，做了一切——但道，不认为自己做了什么——这，是「无为」的最深含义：不是不做，而是：做了，但不执着于「做了」——不居功，不自以为。此之谓天乐——天乐，不是快乐的感受——而是与天道同在的状态：做了一切，但不执着于做了——这种状态，就是天乐。"},{text:"故曰：知天乐者，其生也天行，其死也物化。静而与阴同德，动而与阳同波。……一心定而王天下；其鬼不祟，其魂不疲，一心定而万物服。",tone:"一心定",guide:"知天乐者——知道天乐的人——其生也天行（活着，像天道运行），其死也物化（死去，像万物变化）——生与死，都是自然的——不执着于生，不恐惧于死。静而与阴同德，动而与阳同波——静时，顺应阴的收藏；动时，顺应阳的发散——随道而流动。无天怨，无人非，无物累，无鬼责——四无——不是主动追求这四无——而是：知天乐，自然四无。其动也天，其静也地，一心定而王天下——一心安定，天下自然归王；一心定而万物服——一心安定，万物自然折服。「一心定」——这，是《天道》对「天乐」最精炼的表达：不是追求天乐，而是：一心安定——一心安定，天乐自然在。天乐者，圣人之心以畜天下也——与《天地》「古之畜天下者」完全呼应——圣人，以天乐养育天下。"}]}),n[5]||(n[5]=a("h2",{id:"二、上无为下有为·不易之道",tabindex:"-1"},[t("二、上无为下有为·不易之道 "),a("a",{class:"header-anchor",href:"#二、上无为下有为·不易之道","aria-label":'Permalink to "二、上无为下有为·不易之道"'},"​")],-1)),n[6]||(n[6]=a("h3",{id:"原文-1",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:m,glossary:h,"default-mode":"classic","aria-label":"天道·上无为下有为 原文"}),n[7]||(n[7]=a("h3",{id:"生僻字词-1",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"以天地为宗",pinyin:["zōng"],meaning:"宗：根本、宗旨。以天地为根本。"},{term:"以道德为主",pinyin:["yǐ","dào","dé","wéi","zhǔ"],meaning:"以道德为主体。"},{term:"以无为为常",pinyin:["yǐ","wú","wéi","wéi","cháng"],meaning:"以无为为常态。"}]}),n[8]||(n[8]=a("h3",{id:"核心句引读-1",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"无为则用天下而有余；有为则为天下用而不足",subtitle:"无为的君主，驾驭天下——他，是主动的；有为的君主，被天下驱使——他，是被动的。",lines:[{text:"无为也，则用天下而有余；有为也，则为天下用而不足。故古之人贵夫无为也。",tone:"颠倒",guide:"帝王之德，三个「以……为」——以天地为宗（以天地为根本），以道德为主（以道德为主体），以无为为常（以无为为常态）。无为，则用天下而有余（无为，则驾驭天下，绰绰有余）；有为，则为天下用而不足（有为，则被天下所驱使，疲惫不足）。这两句，是《天道》最重要的政治命题：「用天下」与「为天下用」——两个字的顺序，完全不同。无为的君主，驾驭天下——他，是主动的；天下，是被他驾驭的——有余，因为他不消耗自己。有为的君主，被天下驱使——他，是被动的；天下，在驱使他——不足，因为他在消耗自己。这个颠倒，极为深刻：我们以为：有为，才能掌控天下——庄子说：有为，反而被天下掌控——无为，才是真正的掌控。"},{text:"上必无为而用下，下必有为为天下用。此不易之道也。",tone:"不易之道",guide:"两个对称的命题：第一个：上无为·下亦无为——下与上同德则不臣（臣的职分，是有为——如果臣也无为，臣就失去了臣的职分——上下皆无为，则无人做事，天下无法运转）；第二个：下有为·上亦有为——上与下同道则不主（主的职分，是无为——如果主也有为，主就失去了主的职分——上下皆有为，则君主与臣下无别，天下失去方向）。两个命题，共同指向一个结论：上必无为而用下（上位者，必须无为，来驾驭下位者），下必有为为天下用（下位者，必须有为，来为天下所用）——此不易之道也。上无为，不是上位者什么都不做——而是：上位者，不亲自做具体的事——他，通过无为，来驾驭有为的下位者——这，才是「用天下」的真正含义。"}]}),n[9]||(n[9]=a("h2",{id:"三、本末之序·五末皆末",tabindex:"-1"},[t("三、本末之序·五末皆末 "),a("a",{class:"header-anchor",href:"#三、本末之序·五末皆末","aria-label":'Permalink to "三、本末之序·五末皆末"'},"​")],-1)),n[10]||(n[10]=a("h3",{id:"原文-2",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:g,glossary:y,"default-mode":"classic","aria-label":"天道·本末五末 原文"}),n[11]||(n[11]=a("h3",{id:"生僻字词-2",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"德之末也",pinyin:["dé","zhī","mò","yě"],meaning:"是德的末节（不是德的根本）。"},{term:"教之末也",pinyin:["jiào","zhī","mò","yě"],meaning:"是教化的末节。"},{term:"治之末也",pinyin:["zhì","zhī","mò","yě"],meaning:"是治理的末节。"},{term:"乐之末也",pinyin:["yuè","zhī","mò","yě"],meaning:"是乐的末节。"},{term:"哀之末也",pinyin:["āi","zhī","mò","yě"],meaning:"是哀的末节。"},{term:"神明之位也",pinyin:["shén","míng","zhī","wèi","yě"],meaning:"神明的位置（天地的本然秩序）。"},{term:"萌区有状",pinyin:["méng","qū"],meaning:"萌：萌芽；区：区分。萌芽各有形状（万物各有其样）。"},{term:"盛衰之杀",pinyin:["shā"],meaning:"杀：减少、衰减。盛衰的消长变化。"},{term:"宗庙尚亲",pinyin:["shàng","qīn"],meaning:"尚：崇尚；亲：亲属关系。宗庙，崇尚亲属关系（血缘）。"},{term:"朝廷尚尊",pinyin:["cháo","tíng","shàng","zūn"],meaning:"朝廷，崇尚尊卑（地位）。"},{term:"乡党尚齿",pinyin:["chǐ"],meaning:"齿：年龄。乡里，崇尚年龄（长幼）。"},{term:"行事尚贤",pinyin:["xíng","shì","shàng","xián"],meaning:"做事，崇尚贤能（才能）。"},{term:"大道之序也",pinyin:["dà","dào","zhī","xù","yě"],meaning:"这是大道的秩序。"}]}),n[12]||(n[12]=a("h3",{id:"核心句引读-2",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"五末皆末——须精神之运，心术之动，然后从之者也",subtitle:"五末，是结果，不是原因——你先有内在的德·教·治·乐·哀，然后，五末自然跟随而来。",lines:[{text:"三军五兵之运，德之末也；赏罚利害，五刑之辟，教之末也；礼法度数，刑名比详，治之末也；钟鼓之音，羽旄之容，乐之末也；哭泣衰絰，隆杀之服，哀之末也。",tone:"五末",guide:"五个「末」——五个领域，各有其末节：三军五兵之运（军事），德之末也（德，不是靠军队来体现的——军队，只是德的外在表现的末节）；赏罚利害（刑罚），教之末也；礼法度数（法制），治之末也；钟鼓之音（仪式），乐之末也；哭泣衰絰（丧礼），哀之末也。五个末，都是外在的形式——五个本，都是内在的精神。五末，是对儒家礼教最系统的批判：儒家，恰恰把这五个末节，当成了根本——把军事·刑罚·礼法·仪式·丧礼，当成了德·教·治·乐·哀的核心——庄子说：这些，都是末，不是本。"},{text:"此五末者，须精神之运，心术之动，然后从之者也。末学者，古人有之，而非所以先也。",tone:"须然后从",guide:"此五末者，须精神之运，心术之动，然后从之者也——这五个末节，需要精神的运作，心术的驱动——然后，才跟随而来。这一句，极为重要：五末，不是没有用——而是：五末，是从精神与心术中流出来的——精神在先，心术在先——五末，跟随而来。「须……然后从之」——五末，是结果，不是原因——你先有内在的德·教·治·乐·哀——然后，五末自然跟随而来——如果你直接从五末入手，本末倒置，永远无法到达根本。末学者，古人有之，而非所以先也——古人，知道末学的存在——但古人，把末学放在后面，把本学放在前面——今人，把末学放在前面，这，是失序。"},{text:"夫尊卑先后，天地之行也，故圣人取象焉。……语道而非其序者，非其道也。语道而非其道者，安取道哉！",tone:"天地之行",guide:"君先而臣从，父先而子从，兄先而弟从，长先而少从——六对先后关系，是人道的秩序——夫尊卑先后，天地之行也——尊卑先后，是天地的运行方式——故圣人取象焉。天尊地卑（天地的位置之序），春夏先，秋冬后（四时的时间之序），萌区有状，盛衰之杀（万物的生命之序）——三者，都是自然的——没有人规定天要在上，地要在下——这些，是天地自然的秩序。夫天地至神矣，而有尊卑先后之序，而况人道乎！宗庙尚亲，朝廷尚尊，乡党尚齿，行事尚贤——大道之序也。语道而非其序者，非其道也——谈论道，却违背其秩序——就不是道了。这，是对「骤而语形名赏罚」者的批判：他们，谈论道——但他们，违背了道的秩序——把末放在前，把本放在后——这，不是道，这，是失道。"}]}),n[13]||(n[13]=a("h2",{id:"四、明大道的层级·形名赏罚皆末",tabindex:"-1"},[t("四、明大道的层级·形名赏罚皆末 "),a("a",{class:"header-anchor",href:"#四、明大道的层级·形名赏罚皆末","aria-label":'Permalink to "四、明大道的层级·形名赏罚皆末"'},"​")],-1)),n[14]||(n[14]=a("h3",{id:"原文-3",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:b,glossary:u,"default-mode":"classic","aria-label":"天道·明大道九层 原文"}),n[15]||(n[15]=a("h3",{id:"生僻字词-3",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"分守次之",pinyin:["fēn","shǒu"],meaning:"分守：各守其分（职分与职守）。"},{term:"形名次之",pinyin:["xíng","míng"],meaning:"形名：形体与名称（法家的核心概念：名实相符）。"},{term:"因任次之",pinyin:["yīn","rèn"],meaning:"因任：依据才能任用。"},{term:"原省次之",pinyin:["yuán","xǐng"],meaning:"原省：考察省察（考核）。"},{term:"是非次之",pinyin:["shì","fēi","cì","zhī"],meaning:"判断是非。"},{term:"赏罚次之",pinyin:["shǎng","fá","cì","zhī"],meaning:"赏罚最后。"},{term:"愚知处宜",pinyin:["yú","zhī","chǔ","yí"],meaning:"愚知：愚者与智者；处宜：各处其宜。愚者与智者，各处其适宜的位置。"},{term:"贵贱履位",pinyin:["lǚ","wèi"],meaning:"履位：各就其位。贵贱各就其位。"},{term:"大平",pinyin:["dà","píng"],meaning:"最大的太平（治理的极致）。"},{term:"治之至也",pinyin:["zhì","zhī","zhì","yě"],meaning:"治理的最高境界。"},{term:"骤而语形名",pinyin:["zhòu"],meaning:"骤：急速、突然（不经过前面的层级，直接跳到）。"},{term:"不知其本也",pinyin:["bù","zhī","qí","běn","yě"],meaning:"不知道根本。"},{term:"人之所治也",pinyin:["rén","zhī","suǒ","zhì","yě"],meaning:"是被人治理的人（不是治人的人）。"}]}),n[16]||(n[16]=a("h3",{id:"核心句引读-3",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"九层序列——先明天，道德次之……赏罚次之",subtitle:"法家，从第五层（形名）或第九层（赏罚）开始；儒家，从第三层（仁义）开始；庄子，从第一层（天）开始。",lines:[{text:"是故古之明大道者，先明天而道德次之，道德已明而仁义次之，仁义已明而分守次之，分守已明而形名次之，形名已明而因任次之，因任已明而原省次之，原省已明而是非次之，是非已明而赏罚次之。",tone:"九层",guide:"九个层级，从高到低：天→道德→仁义→分守→形名→因任→原省→是非→赏罚。九层，是一个严格的序列——每一层，必须在上一层「已明」之后，才能进入。「先明天」——第一步，是明白天道——不是天文，而是：天道的运行方式——虚静无为。这个九层序列，是《天道》对治理哲学最完整的表达：法家，从第五层（形名）或第九层（赏罚）开始；儒家，从第三层（仁义）开始；庄子，从第一层（天）开始。庄子的批判，不是说形名·赏罚不能用——而是说：你必须从天道开始，一层一层往下——跳过前面的层级，直接从形名·赏罚开始——这，是「骤而语形名赏罚」——不知其本。"},{text:"骤而语形名，不知其本也；骤而语赏罚，不知其始也。倒道而言，迕道而说者，人之所治也，安能治人！",tone:"骤而语",guide:"五变而形名可举（经过五个层级，才可以谈形名），九变而赏罚可言（经过九个层级，才可以谈赏罚）——骤而语形名，不知其本也（跳过前面，直接谈形名——不知道根本）；骤而语赏罚，不知其始也。倒道而言，迕道而说者——倒着说道，违背道来说的人——人之所治也，安能治人！——是被人治理的人，怎么能治理别人！这一句，极为犀利：骤而语形名赏罚的人——他，是「倒道而言」的——他，是「被人治理」的——他，没有资格治理别人。"},{text:"骤而语形名赏罚，此有知治之具，非知治之道。可用于天下，不足以用天下。此之谓辩士，一曲之人也。",tone:"辩士",guide:"有知治之具，非知治之道——知道治理的工具，但不知道治理的道。可用于天下，不足以用天下——可以被天下所用（作为工具），但不足以驾驭天下——这两句，与「无为则用天下，有为则为天下用」完全呼应：骤而语形名赏罚的人——是「为天下用」的人——不是「用天下」的人——他，是工具，不是主人。此之谓辩士，一曲之人也——这，叫做辩士，片面局限的人——只知道一个角度，一个层面——只知道形名赏罚，不知道天道——这，是《天道》对法家（以及一切只知末节的人）的最终判断。礼法数度，形名比详，古人有之。此下之所以事上，非上之所以畜下也——礼法形名，是下位者的工具——不是上位者的工具——上位者，用虚静无为来养育天下——如果上位者，用礼法形名来管理下位者——他，就把自己降格为下位者了。"}]}),n[17]||(n[17]=a("h2",{id:"五、尧舜问答·天德而出宁",tabindex:"-1"},[t("五、尧舜问答·天德而出宁 "),a("a",{class:"header-anchor",href:"#五、尧舜问答·天德而出宁","aria-label":'Permalink to "五、尧舜问答·天德而出宁"'},"​")],-1)),n[18]||(n[18]=a("h3",{id:"原文-4",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-4","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:x,glossary:c,"default-mode":"classic","aria-label":"天道·尧舜问答 原文"}),n[19]||(n[19]=a("h3",{id:"生僻字词-4",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"吾不敖无告",pinyin:["ào","wú","gào"],meaning:"敖：傲慢、轻视；无告：无处申诉的人（孤苦无依者）。我不轻视无处申诉的人。"},{term:"不废穷民",pinyin:["bù","fèi","qióng","mín"],meaning:"不废弃穷苦的百姓。"},{term:"苦死者",pinyin:["kǔ","sǐ","zhě"],meaning:"为死者感到痛苦（悼念死者）。"},{term:"天德而出宁",pinyin:["tiān","dé","ér","chū","níng"],meaning:"天德：天的德性；出宁：自然流出安宁。天的德性自然流出安宁。"},{term:"胶胶扰扰乎",pinyin:["jiāo","jiāo","rǎo","rǎo"],meaning:"胶胶扰扰：纷扰忙碌的样子。多么纷扰忙碌啊！"},{term:"天地而已矣",pinyin:["tiān","dì","ér","yǐ","yǐ"],meaning:"效法天地，就够了。"}]}),n[20]||(n[20]=a("h3",{id:"核心句引读-4",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"美则美矣，而未大也——人之合与天之合",subtitle:"尧的用心，停留在「与人和」——还没有到达「与天和」。",lines:[{text:"尧曰：吾不敖无告，不废穷民，苦死者，嘉孺子而哀妇人，此吾所以用心已。舜曰：美则美矣，而未大也。",tone:"美与未大",guide:"尧，描述自己的用心——不敖无告（不轻视无处申诉的人），不废穷民（不废弃穷苦的百姓），苦死者（为死者感到痛苦），嘉孺子而哀妇人（爱护幼儿，怜悯妇人）——四件事，都是仁政的具体表现——都是好的——都是儒家所推崇的。舜，一句话：美则美矣，而未大也——美是美的，但还不够大。这一句，是整段的核心张力：「美」与「大」的区别——「美」，是人间层面的好——是仁义·悲悯·爱护——是「与人和」的层面；「大」，是天道层面的好——是天德·日月·四时——是「与天和」的层面。尧的用心，停留在「与人和」——还没有到达「与天和」——所以：美，但未大。"},{text:"舜曰：天德而出宁，日月照而四时行，若昼夜之有经，云行而雨施矣！",tone:"大",guide:"舜，给出了「大」的答案——天德而出宁（天的德性，自然流出安宁——不是主动去安宁百姓，而是：天德自然流出，安宁自来），日月照而四时行（日月，不是主动去照耀——四时，不是主动去运行——这些，都是自然的），若昼夜之有经（像昼夜有其规律一样——昼夜，不是被人安排的），云行而雨施矣（云自然运行，雨自然降施）。舜的「大」，是什么？不是更努力地去关心百姓——而是：像天道一样运行——天德自然流出，日月自然照耀，云行自然雨施——不执着于「我在关心百姓」——而是：自然地，天德流出，安宁自来。这，与第1段「天道运而无所积」完全呼应：不积滞于「我在用心」，而是：天德自然流出。"},{text:"尧曰：胶胶扰扰乎！子，天之合也；我，人之合也。……故古之王天下者，奚为哉？天地而已矣！",tone:"天地而已",guide:"尧，听了舜的话，说——胶胶扰扰乎！多么纷扰忙碌啊！——尧，在说自己的「用心」——不敖无告·不废穷民·苦死者·嘉孺子哀妇人——这些，是「胶胶扰扰」的——是纷扰忙碌的，是执着于「用心」的。子，天之合也；我，人之合也——你，是与天相合的人；我，是与人相合的人——尧，承认了自己的局限：他，是「人之合」——在人间层面做到了极致——但舜，是「天之合」——在天道层面自然运行。夫天地者，古之所大也——故古之王天下者，奚为哉？天地而已矣——王天下，不需要做很多——只需要：效法天地——天地，运而无所积，虚静无为——效法天地，就是王天下的全部。"}]}),n[21]||(n[21]=a("h2",{id:"六、孔子见老聃·仁义之辩",tabindex:"-1"},[t("六、孔子见老聃·仁义之辩 "),a("a",{class:"header-anchor",href:"#六、孔子见老聃·仁义之辩","aria-label":'Permalink to "六、孔子见老聃·仁义之辩"'},"​")],-1)),n[22]||(n[22]=a("h3",{id:"原文-5",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-5","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:f,glossary:k,"default-mode":"classic","aria-label":"天道·孔子见老聃 原文"}),n[23]||(n[23]=a("h3",{id:"生僻字词-5",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"免而归居",pinyin:["miǎn"],meaning:"免：免职、退休。退职回家居住。"},{term:"试往因焉",pinyin:["yīn"],meaning:"因：借助、依托。试着去借助他（请他帮忙）。"},{term:"老聃中其说",pinyin:["zhòng"],meaning:"中：打断、插入。老聃打断了他的讲说。"},{term:"要在仁义",pinyin:["yào","zài","rén","yì"],meaning:"要点在于仁义。"},{term:"中心物恺",pinyin:["wù","kǎi"],meaning:"中心：内心；物恺：对万物和乐（恺：和乐、喜悦）。内心对万物和乐。"},{term:"放德而行",pinyin:["fàng","dé"],meaning:"放：依循、顺应。顺应德性而行。"},{term:"遁遁而趋",pinyin:["dùn","dùn"],meaning:"遁遁：自然退隐、顺势而行的样子。自然顺势地前行。"}]}),n[24]||(n[24]=a("h3",{id:"核心句引读-5",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"兼爱迂·无私乃私——放德而行，遁遁而趋，已至矣",subtitle:"真正的仁义，是不知道自己在行仁义——一旦知道，并标榜，就失去了本然。",lines:[{text:"老聃曰：请问：何谓仁义？孔子曰：中心物恺，兼爱无私，此仁义之情也。老聃曰：意，几乎后言！夫兼爱，不亦迂夫！无私焉，乃私也。",tone:"兼爱无私",guide:"孔子，要把书藏在周室——老聃，不答应——孔子，于是展开十二经来讲说——老聃，打断了他：「大谩，愿闻其要。」——太繁杂了，希望听其要点——孔子，给出要点：「要在仁义。」老聃问：仁义，人之性邪？孔子答：然，君子不仁则不成，不义则不生——仁义，真人之性也。老聃又问：何谓仁义？孔子答：中心物恺（内心对万物和乐），兼爱无私（兼爱，无私）——此仁义之情也。老聃，叹了一口气——意，几乎后言！——然后，两句批判：「夫兼爱，不亦迂夫！」（兼爱，不也太迂腐了吗——你，把「爱」变成了一个需要努力达到的目标——真正的爱，是本然的，不需要「兼」）；「无私焉，乃私也。」（你说「无私」——但「无私」，是你执着的目标——你执着于「无私」——这种执着，本身就是一种「私」——真正的无私，不知道自己无私）。"},{text:"夫子若欲使天下无失其牧乎？则天地固有常矣，日月固有明矣，星辰固有列矣，禽兽固有群矣，树木固有立矣。夫子亦放德而行，遁遁而趋，已至矣！",tone:"放德而行",guide:"老聃，给出了正面的答案——夫子若欲使天下无失其牧乎？（你，想要使天下不失去本性吗？）则——看：天地固有常（天地，本来就有其常规），日月固有明（日月，本来就有其光明），星辰固有列（星辰，本来就有其排列），禽兽固有群（禽兽，本来就有其群落），树木固有立（树木，本来就有其生长）——五个「固有」——这些，都不需要人来安排——它们，本来就有其秩序。夫子亦放德而行，遁遁而趋，已至矣！——你，也顺应德性而行，自然顺势地前行，就已经到达了！「放德而行」——不是主动去推行仁义——而是：顺应本然的德性，自然而行。这，与舜的「天德而出宁」完全呼应：顺应德性，自然而行，天下自然不失其本性。"},{text:"又何偈偈乎揭仁义，若击鼓而求亡子焉！意，夫子乱人之性也。",tone:"乱人之性",guide:"又何偈偈乎揭仁义（还要急切地高举标榜仁义做什么！）——若击鼓而求亡子焉（像敲鼓来寻找逃跑的孩子一样）——这个比喻，极为精准：孩子逃跑了——你，敲鼓来找他——敲鼓，声音很大——但孩子，听到鼓声，会跑得更远——因为：鼓声，告诉他，有人在找他——他，会躲得更深。仁义，也是如此：人的本性，本来就有仁义——你，高举标榜仁义——但这种标榜，反而让人意识到：「仁义」，是一个外在的标准——人，开始用这个标准来衡量自己——开始表演仁义，而不是本然地行仁义——本性，反而失去了。意，夫子乱人之性也——哎，夫子是在扰乱人的本性啊！——这，是老聃对孔子最严厉的批判——不是说孔子坏——而是说：孔子的做法，结果是乱人之性——好意，但结果相反。"}]}),n[25]||(n[25]=a("h2",{id:"七、士成绮见老子",tabindex:"-1"},[t("七、士成绮见老子 "),a("a",{class:"header-anchor",href:"#七、士成绮见老子","aria-label":'Permalink to "七、士成绮见老子"'},"​")],-1)),n[26]||(n[26]=a("h3",{id:"原文-6",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-6","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:z,glossary:P,"default-mode":"classic","aria-label":"天道·士成绮见老子 原文"}),n[27]||(n[27]=a("h3",{id:"生僻字词-6",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"士成绮",pinyin:["shì","chéng","qǐ"],meaning:"庄子虚构的人物，来求见老子的求道者。"},{term:"雁行避影",pinyin:["yàn","xíng","bì","yǐng"],meaning:"雁行：像大雁飞行一样斜行（表示恭敬退让）；避影：避开自己的影子（极度恭敬）。"}]}),n[28]||(n[28]=a("h3",{id:"核心句引读-6",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"呼我牛谓之牛·呼我马谓之马·吾服也恒服",subtitle:"「漠然」，是一种无为的回应——不回应，反而是最有力的回应。",lines:[{text:"今吾观子，非圣人也。鼠壤有余蔬而弃妹，不仁也！生熟不尽于前，而积敛无崖。老子漠然不应。",tone:"漠然",guide:"士成绮，是一个求道者——百舍重趼而不敢息（走了极远的路，脚上磨出层层老茧，不敢停息）——这种求道的诚意，是真实的——但他，见到老子之后，大失所望——两个批评：「鼠壤有余蔬而弃妹，不仁也」（鼠穴旁有多余的蔬菜却丢弃不管——不仁）；「生熟不尽于前，而积敛无崖」（面前吃不完，却还无边际地积敛财物——贪婪）。士成绮，用儒家的标准来评价老子——但老子——「漠然不应」——这个「漠然不应」，极为重要：不是老子没有听到，不是不屑于回应——而是：老子，根本不在意这些批评——因为：这些批评，来自士成绮的标准，不是老子的标准——老子，不需要为别人的标准辩护。"},{text:"昔者子呼我牛也而谓之牛；呼我马也而谓之马。苟有其实，人与之名而弗受，再受其殃。吾服也恒服，吾非以服有服。",tone:"恒服",guide:"第二天，士成绮又来了——「昔者吾有剌于子，今吾心正郤矣，何故也？」（昨天我有言语冒犯你，现在我心中的芥蒂消退了，是什么原因呢？）——这个转变，是老子「漠然不应」的效果：老子，没有辩解，没有反击——他，只是漠然——但这种漠然，反而让士成绮，自己消化了自己的批评——一夜之间，芥蒂消退。老子答：昔者子呼我牛也而谓之牛；呼我马也而谓之马（昨天你叫我牛，我就是牛；叫我马，我就是马）——苟有其实，人与之名而弗受，再受其殃（如果有那个实质，别人给了名称却不接受，就会再受祸殃）——吾服也恒服，吾非以服有服（我一贯顺服，我不是因为你的批评才顺服的——本然的顺服，不是有为的顺服）。"},{text:"而容崖然，而目冲然，而颡頯然，而口阚然，而状义然。似系马而止也，动而持，发也机，察而审，知巧而睹于泰，凡以为不信。边竟有人焉，其名为窃。",tone:"边竟",guide:"士成绮雁行避影，履行遂进（极度恭敬地靠近），而问修身若何。老子说：而容崖然（你的容貌高傲矜持），而目冲然（眼神锐利冲射），而颡頯然（额头紧绷突出），而口阚然（嘴巴气势逼人），而状义然（神态以义自居）——似系马而止也（像被拴住的马——想动却被束缚），动而持（动时克制），发也机（发动时一触即发），察而审（审察仔细），知巧而睹于泰（聪明机巧而流露出骄傲）——凡以为不信（凡此种种，都让人不信任）——边竟有人焉，其名为窃（边界上有这样的人，他的名字叫做「窃」）——「窃」——用外在姿态（容崖·目冲·状义）来偷取道，不是真正的修道——停留在「边界」——不内不外——这，是老子对士成绮的最终判断。"}]}),n[29]||(n[29]=a("h2",{id:"八、老子论至人·道·形德仁义",tabindex:"-1"},[t("八、老子论至人·道·形德仁义 "),a("a",{class:"header-anchor",href:"#八、老子论至人·道·形德仁义","aria-label":'Permalink to "八、老子论至人·道·形德仁义"'},"​")],-1)),n[30]||(n[30]=a("h3",{id:"原文-7",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-7","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:q,glossary:w,"default-mode":"classic","aria-label":"天道·老子论至人 原文"}),n[31]||(n[31]=a("h3",{id:"生僻字词-7",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-7","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"故万物备",pinyin:["gù","wàn","wù","bèi"],meaning:"所以万物具备（道包含一切）。"},{term:"形德仁义",pinyin:["xíng","dé","rén","yì"],meaning:"形·德·仁义。形德仁义，神之末也：都是精神（神）的末节。"},{term:"通乎道",pinyin:["tōng","hū","dào"],meaning:"通达于道。至人修道的最高层。"},{term:"合乎德",pinyin:["hé","hū","dé"],meaning:"合于德。至人修道的第二层。"},{term:"退仁义",pinyin:["tuì","rén","yì"],meaning:"仁义退后。道与德在前，仁义在后，不以仁义为首要。"},{term:"宾礼乐",pinyin:["bīn","lǐ","yuè"],meaning:"礼乐为宾。礼乐可以有，但不是核心，道与德才是主人。"},{term:"外天地",pinyin:["wài","tiān","dì"],meaning:"不执着于天地。外天地，遗万物，而神未尝有所困。"}]}),n[32]||(n[32]=a("h3",{id:"核心句引读-7",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"通乎道，合乎德，退仁义，宾礼乐——至人之心有所定矣",subtitle:"「退仁义」——不是说仁义不好——而是：仁义，退后——道与德，在前。",lines:[{text:"夫道，于大不终，于小不遗，故万物备。广广乎其无不容也，渊渊乎其不可测也。形德仁义，神之末也，非至人孰能定之！",tone:"道之全",guide:"老子论至人——夫道，于大不终（对大，不穷尽），于小不遗（对小，不遗漏）——故万物备（所以万物具备——道包含一切）。广广乎其无不容也（广大无边，没有什么不容纳的），渊渊乎其不可测也（深远无比，不可测度）。形德仁义，神之末也——形·德·仁义，都是精神（神）的末节——非至人孰能定之！——不是至人，谁能安定它们呢！这，是《天道》对「形德仁义」的定位：它们，都是「神」的末节——至人，从精神（本）出发——精神安定，则形·德·仁义自然安定。"},{text:"夫至人有世，不亦大乎，而不足以为之累；天下奋柄而不与之偕；审乎无假而不与利迁；极物之真，能守其本。故外天地，遗万物，而神未尝有所困也。",tone:"至人",guide:"至人有世，不亦大乎，而不足以为之累（至人拥有天下，不是很大吗？却不足以成为他的拖累）；天下奋柄而不与之偕（天下争夺权柄，他不参与）；审乎无假而不与利迁（明察于不依赖外物，不被利益所迁移）；极物之真，能守其本（穷尽万物的本真，能守住根本）。故外天地，遗万物（不执着于天地，放下万物），而神未尝有所困也（精神从未困扰）。「外天地，遗万物」——不是不要天地万物——而是：不执着于它们——精神，不被它们所困——这，与《天地》「忘乎物，忘乎天，忘己，入于天」完全呼应。"},{text:"通乎道，合乎德，退仁义，宾礼乐，至人之心有所定矣！",tone:"有所定",guide:"通乎道（通达于道——最高层），合乎德（合于德——第二层），退仁义（仁义退后——第三层），宾礼乐（礼乐为宾——第四层）——四个动作，构成一个层级——与第4段「明大道九层序列」完全呼应：至人，从天道出发，合于德，退仁义，宾礼乐——这，是九层序列的个人修道版本。「退仁义」——不是说仁义不好——而是：仁义，退后——道与德，在前——不以仁义为首要，而以道德为首要；「宾礼乐」——礼乐，作为宾客——不是主人——礼乐，可以有，但不是核心。至人之心有所定矣！——「有所定」——这，是《天道》对至人最终状态的描述：心，安定了——不是因为外在的安定，而是：通乎道·合乎德·退仁义·宾礼乐——这四个，做到了，心自然安定。"}]}),n[33]||(n[33]=a("h2",{id:"九、知者不言·言传书之困",tabindex:"-1"},[t("九、知者不言·言传书之困 "),a("a",{class:"header-anchor",href:"#九、知者不言·言传书之困","aria-label":'Permalink to "九、知者不言·言传书之困"'},"​")],-1)),n[34]||(n[34]=a("h3",{id:"原文-8",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-8","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:j,glossary:T,"default-mode":"classic","aria-label":"天道·知者不言 原文"}),n[35]||(n[35]=a("h3",{id:"生僻字词-8",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-8","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"书不过语",pinyin:["shū","bù","guò","yǔ"],meaning:"书，不过是语言的记录。"},{term:"语有贵也",pinyin:["yǔ","yǒu","guì","yě"],meaning:"语言，有其可贵之处。"},{term:"意有所随",pinyin:["yì","yǒu","suǒ","suí"],meaning:"意，有其所跟随的东西（意，跟随着更深的东西）。"},{term:"悲夫",pinyin:["bēi","fū"],meaning:"悲哀啊！"}]}),n[36]||(n[36]=a("h3",{id:"核心句引读-8",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"书·语·意·意之所随——不可以言传",subtitle:"每一层，都比上一层更深——但每一层，都无法完全传递上一层——道，无法被传递。",lines:[{text:"世之所贵道者，书也。书不过语，语有贵也。语之所贵者，意也，意有所随。意之所随者，不可以言传也，而世因贵言传书。",tone:"四层",guide:"四个层级，层层递进：书（世人认为能得道的东西）——书不过语（书，不过是语言的记录）——语之所贵者，意（语言，贵在意——意思·意境）——意有所随（意，跟随着更深的东西）——意之所随者，不可以言传（意所跟随的那个东西——这，才是真正的道——但这个东西，不可以用言语传递）。这个四层递进，是《天道》认识论的核心：书→语→意→意之所随（道）——可见·可传·可感·不可言传。每一层，都比上一层更深——但每一层，都无法完全传递上一层——书，传递语；语，传递意；意，感受道——但道，无法被传递。世人，停留在「书」与「语」的层面——以为书与语，可以传递道——但书与语，只能传递到「意」——「意之所随」，永远无法被书与语所传递。"},{text:"故视而可见者，形与色也；听而可闻者，名与声也。悲夫！世人以形色名声为足以得彼之情。夫形色名声，果不足以得彼之情，则知者不言，言者不知，而世岂识之哉！",tone:"知者不言",guide:"视而可见者，形与色（眼睛，只能看见形体与颜色）；听而可闻者，名与声（耳朵，只能听到名称与声音）——形·色·名·声——这四者，是感官所能感知的全部——但道，不在形·色·名·声之中。悲夫！世人以形色名声为足以得彼之情——世人，用感官来寻找道——用眼睛看形色，用耳朵听名声——以为这样，可以得到道——但道，不在形色名声之中——感官，永远无法触及道。知者不言，言者不知——这，是《天道》全篇最著名的一句话——也是《老子》「知者不博，博者不知」的呼应：真正知道道的人，不说——因为：道，不可以言传——说了，就不是道了；说的人，不知道——因为：能说出来的，都是「意」以下的层面——真正的道（意之所随），无法被说出——所以：说了很多的人，说的都不是道。"}]}),n[37]||(n[37]=a("h2",{id:"十、轮扁斫轮·道不可传",tabindex:"-1"},[t("十、轮扁斫轮·道不可传 "),a("a",{class:"header-anchor",href:"#十、轮扁斫轮·道不可传","aria-label":'Permalink to "十、轮扁斫轮·道不可传"'},"​")],-1)),n[38]||(n[38]=a("h3",{id:"原文-9",tabindex:"-1"},[t("原文 "),a("a",{class:"header-anchor",href:"#原文-9","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:G,glossary:C,"default-mode":"classic","aria-label":"天道·轮扁斫轮 原文"}),n[39]||(n[39]=a("h3",{id:"生僻字词-9",tabindex:"-1"},[t("生僻字词 "),a("a",{class:"header-anchor",href:"#生僻字词-9","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(s,{items:[{term:"释椎凿而上",pinyin:["shì","zhuī","záo"],meaning:"释：放下；椎：木槌；凿：凿子。放下木槌和凿子，走上堂来。"},{term:"圣人之言也",pinyin:["shèng","rén","zhī","yán","yě"],meaning:"圣人的言论。"},{term:"斫轮",pinyin:["zhuó","lún"],meaning:"砍削制作车轮。轮扁斫轮于堂下：工匠在堂下做车轮。"},{term:"糟粕",pinyin:["zāo","pò"],meaning:"酿酒剩下的渣滓。古人之糟粕已夫：圣人的精华（道）随其而去，留下的文字是渣滓。"},{term:"不徐不疾",pinyin:["bù","xú","bù","jí"],meaning:"不快不慢。斫轮的分寸——得之于手而应于心，口不能言，有数存乎其间。"},{term:"得之于手",pinyin:["dé","zhī","yú","shǒu"],meaning:"手上得到。得之于手而应于心：手艺与心神相应，无法言传。"}]}),n[40]||(n[40]=a("h3",{id:"核心句引读-9",tabindex:"-1"},[t("核心句引读 "),a("a",{class:"header-anchor",href:"#核心句引读-9","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(r,{title:"古之人与其不可传也死矣，然则君之所读者，古人之糟粕已夫！",subtitle:"书，是糟粕——道，在书之外，在你自己的「斫轮」中。",lines:[{text:"桓公读书于堂上，轮扁斫轮于堂下，释椎凿而上，问桓公曰：敢问：公之所读者，何言邪？公曰：圣人之言也。曰：圣人在乎？公曰：已死矣。曰：然则君之所读者，古人之糟粕已夫！",tone:"堂上堂下",guide:"这个场景，极为精心设计：堂上——桓公，读书——书·语言·圣人之言——抽象的，精神的；堂下——轮扁，斫轮——椎凿·车轮·手艺——具体的，身体的。轮扁，放下椎凿，走上堂来——从「堂下」走到「堂上」——从具体，走向抽象——从手艺，走向言论。三问三答，极为简洁：圣人之言（是圣人的言论）；圣人在乎（圣人还在世吗）；已死矣（已经死了）；古人之糟粕已夫（那就是古人的糟粕罢了！）。这个逻辑，极为犀利：圣人，有其道——圣人，把道写成了言论——但圣人，死了——带走了「意之所随」——带走了那个「不可以言传」的东西——留下了言论——留下了书——留下了「语」——但「语」，只是道的外壳——道的实质，随圣人而去了——留下的，只是糟粕。"},{text:"寡人读书，轮人安得议乎！有说则可，无说则死！",tone:"桓公之怒",guide:"桓公，愤怒了——「寡人读书，轮人安得议乎！」（我读书，做车轮的工匠，怎么能议论呢！）——这一句，是桓公的傲慢——也是世人的傲慢：「读书」，是高贵的——「斫轮」，是低贱的——低贱的，怎么能议论高贵的？但这种傲慢，恰恰是庄子要批判的：桓公，以为读书（书·语）高于斫轮（手艺·身体）——但轮扁，要证明：斫轮的手艺，比读书，更接近道——因为：斫轮，有「不可言传」的东西——而读书，只有「可以言传」的东西。「有说则可，无说则死！」——桓公，给了轮扁说话的机会——但同时，用死亡来威胁——这，是权力对真理的威胁——但轮扁，不惧怕——因为：他，有真正的道理。"},{text:"斫轮，徐则甘而不固，疾则苦而不入，不徐不疾，得之于手而应于心，口不能言，有数存乎其间。臣不能以喻臣之子，臣之子亦不能受之于臣，是以行年七十而老斫轮。",tone:"有数",guide:"轮扁，用自己的手艺来论证——斫轮，有三种状态：徐则甘而不固（慢了，太顺滑，不牢固——太慢，力度不够，车轮松散）；疾则苦而不入（快了，太涩滞，进不去——太快，力度过猛，凿子卡住）；不徐不疾（不慢不快——这，才是对的）。得之于手而应于心（手上得到了，心里也感应到了），口不能言，有数存乎其间（嘴巴无法说出——但其中，有一种分寸存在）。这个「数」，是什么？不是数字，不是规则——而是：那个「不徐不疾」的分寸——那个只能在做的过程中体会，无法用语言描述的东西。臣不能以喻臣之子，臣之子亦不能受之于臣（我，无法把这个传授给我的儿子；我的儿子，也无法从我这里接受它）——是以行年七十而老斫轮（所以走到七十岁，还在做车轮）。为什么无法传授？因为这个「数」，不在语言中——它，在做的过程中——在手与心的感应中——语言，无法传递它——只能，自己做，自己体会。"},{text:"古之人与其不可传也死矣，然则君之所读者，古人之糟粕已夫！",tone:"糟粕",guide:"这两句，是全篇最有力的收束——古之人与其不可传也死矣（古人，连同那个不可传递的东西，一起死去了——古人（圣人），有道——道，是「不可传」的——古人，死了——道，随古人而死——留下的，只有言论）；然则君之所读者，古人之糟粕已夫（那么您所读的，不过是古人的糟粕罢了）。轮扁，用自己的经验，证明了这一点：他的「数」，无法传给儿子——圣人的「道」，同样无法传给后人——两者，是同一个道理的两种体现。这，不是对圣人的否定——而是：对「以书传道」的否定——圣人，是有道的——但圣人的道，无法通过书来传递——书，只是糟粕——道，在书之外——在你自己的「斫轮」中——在你自己的「不徐不疾·得之于手而应于心」中。"}]}),n[41]||(n[41]=l(`<h2 id="脉络逻辑链" tabindex="-1">脉络逻辑链 <a class="header-anchor" href="#脉络逻辑链" aria-label="Permalink to &quot;脉络逻辑链&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1段·起（天道虚静论·天乐）</span></span>
<span class="line"><span>    天道运而无所积·虚静恬淡寂漠无为·天乐无言而心说</span></span>
<span class="line"><span>    → 全篇主轴：虚静无为，是本</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第2段·政（上无为下有为·不易之道）</span></span>
<span class="line"><span>    无为则用天下而有余·上必无为而用下·此不易之道</span></span>
<span class="line"><span>    → 政治结构：上位无为，下位有为</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第3段·析（本末之序·五末皆末）</span></span>
<span class="line"><span>    三军五兵德之末·赏罚教之末·礼法治之末·钟鼓乐之末·哭泣哀之末</span></span>
<span class="line"><span>    → 五末皆末：外在形式不是根本</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第4段·立（明大道的层级·形名赏罚皆末）</span></span>
<span class="line"><span>    先明天而道德次之·九变而赏罚可言·骤而语形名不知其本</span></span>
<span class="line"><span>    → 九层序列：从天道到赏罚，逐层而下</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第5段·证（尧舜问答·天德而出宁）</span></span>
<span class="line"><span>    吾不敖无告不废穷民·美则美矣而未大也·天德而出宁</span></span>
<span class="line"><span>    → 人之合与天之合：尧美舜大</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第6段·批（孔子见老聃·仁义之辩）</span></span>
<span class="line"><span>    兼爱不亦迂夫·无私焉乃私也·放德而行遁遁而趋已至矣</span></span>
<span class="line"><span>    → 批判标榜仁义：乱人之性</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第7段·证（士成绮见老子）</span></span>
<span class="line"><span>    呼我牛也谓之牛·呼我马也谓之马·吾服也恒服</span></span>
<span class="line"><span>    → 漠然不应：不被外在评价定义</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第8段·立（老子论至人·道·形德仁义）</span></span>
<span class="line"><span>    形德仁义神之末也·通乎道合乎德退仁义宾礼乐·至人之心有所定</span></span>
<span class="line"><span>    → 至人：从道出发，仁义礼乐退为宾</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第9段·识（知者不言·言传书之困）</span></span>
<span class="line"><span>    书不过语·语之所贵者意·意之所随者不可以言传</span></span>
<span class="line"><span>    → 认识论：道不可言传，知者不言</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第10段·合（轮扁斫轮·道不可传）</span></span>
<span class="line"><span>    不徐不疾得之于手而应于心·口不能言有数存乎其间·古人之糟粕已夫</span></span>
<span class="line"><span>    → 全篇收束：道在做的过程中，不在书中</span></span></code></pre></div><p><strong>全篇主线</strong>：从虚静天乐起，经上无为下有为的政治结构、五末九层，以尧舜问答、孔子见老聃、士成绮三重印证，立至人之境，最终以知者不言、轮扁斫轮收束——虚静无为是本，道不可言传。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h3 id="第一问·「运而无所积」——这是一种什么样的状态" tabindex="-1">第一问·「运而无所积」——这是一种什么样的状态？ <a class="header-anchor" href="#第一问·「运而无所积」——这是一种什么样的状态" aria-label="Permalink to &quot;第一问·「运而无所积」——这是一种什么样的状态？&quot;">​</a></h3><p>《天道》开篇，三道无积——天道·帝道·圣道，运而无所积。「积」，是什么？积，是执着的物理形态——当你执着于某件事，你就在那里「积」——你，停留在那里，不再流动。</p><p>天道，为什么不积？因为：天道，没有执着——天道，不执着于任何地方——所以，天道，永远在运行，永远不停留。「运而无所积」，在人的层面，是什么？是：做了，但不执着于做了；是：给了，但不执着于给了；是：成就了，但不执着于成就了。庄子在第1段说：「赍万物而不为戾；泽及万世而不为仁；长于上古而不为寿；覆载天地·刻雕众形而不为巧。」四个「不为」——做了，但不认为自己做了——这，就是「运而无所积」的人间体现。</p><p>今天，我们面临的最大「积」，是什么？积于成就（执着于自己做了什么）、积于身份（执着于自己是什么人）、积于观点（执着于自己的想法是对的）、积于关系（执着于别人对自己的看法）、积于过去（执着于已经发生的事）。每一种「积」，都是阻碍——都让道，无法在你身上流动。「运而无所积」——不是说什么都不做——而是：做了，就放下——不在任何地方停留——这，是天道的运行方式，也是人道的最高境界。</p><h3 id="第二问·「上无为·下有为」——这个结构-今天还适用吗" tabindex="-1">第二问·「上无为·下有为」——这个结构，今天还适用吗？ <a class="header-anchor" href="#第二问·「上无为·下有为」——这个结构-今天还适用吗" aria-label="Permalink to &quot;第二问·「上无为·下有为」——这个结构，今天还适用吗？&quot;">​</a></h3><p>《天道》的政治哲学核心：上必无为而用下，下必有为为天下用。这个结构，在今天，面临一个根本性的挑战：今天，很多人认为：领导者，应该冲在前面，亲力亲为——「上无为」，听起来像是不负责任。</p><p>但庄子的「上无为」，不是「什么都不做」——而是：上位者，不亲自做具体的事——他，做的是：明天道（虚静无为的根基）、定方向（本在于上·要在于主）、用人才（上必无为而用下）、不干扰（让下位者有为）。这，与今天最好的管理哲学，完全吻合：最好的领导者，不是最忙的领导者——而是：让团队最能发挥的领导者——他，定方向，用人才，不干扰——这，就是「上无为而用下」。「无为则用天下而有余；有为则为天下用而不足」——这，是今天很多领导者的真实困境：越忙，越被事务所困——越有为，越「为天下用」——越无为（放权·信任·不干扰），越「用天下」。</p><p>但「上无为」有一个前提：上位者，必须先「明天道」——必须先有「虚静恬淡寂漠无为」的根基——没有这个根基的「无为」，只是懒惰，不是无为。</p><h3 id="第三问·「古人之糟粕」——我们今天读的-是糟粕吗" tabindex="-1">第三问·「古人之糟粕」——我们今天读的，是糟粕吗？ <a class="header-anchor" href="#第三问·「古人之糟粕」——我们今天读的-是糟粕吗" aria-label="Permalink to &quot;第三问·「古人之糟粕」——我们今天读的，是糟粕吗？&quot;">​</a></h3><p>轮扁斫轮，是《天道》最挑战人的命题：古人之糟粕已夫！这，是不是说：读书，没有用？是不是说：经典，没有价值？不是——庄子，不是在否定书的价值——而是在说：书，是道的外壳，不是道本身。</p><p>书，有两种读法：第一种读法——把书当成道本身：以为读了书，就得了道——以为背了经典，就掌握了真理——这种读法，读到的，是糟粕——因为：你，把外壳当成了内容。第二种读法——把书当成指向道的手指：书，指向道——但道，不在书中——书，是地图；道，是地方——地图，不是地方——你，要去的，是地方，不是地图——这种读法，书，是有价值的——因为：你，用书来指引方向，但不停留在书中。</p><p>轮扁的「数」，给了我们答案：道，在「不徐不疾·得之于手而应于心」中——在做的过程中——在体验中——不在书中。所以：读书，是必要的——但读书，不是终点——读书之后，还要：做——在做中，体会那个「有数存乎其间」——这，才是读书的正确方式。</p><blockquote><p>书，是糟粕——但糟粕，也有用——酿酒的糟粕，可以做醋——关键是：不要把糟粕，当成酒。</p></blockquote><h2 id="现代思考" tabindex="-1">现代思考 <a class="header-anchor" href="#现代思考" aria-label="Permalink to &quot;现代思考&quot;">​</a></h2><p><strong>思考一·虚静与专注力危机</strong></p><blockquote><p>《天道》的「虚静」，在今天，有了全新的紧迫性——今天，我们面临的，是专注力危机：手机·推送·通知·算法——每一个，都在打断我们的「静」——每一个，都在制造「积」。「圣人之静，非曰静也善，故静也——万物无足以挠心者，故静也。」今天，万物，无时无刻不在挠心——不是因为万物变得更强大了——而是：我们，给了万物挠心的权力——我们，把手机放在床头——我们，开启了所有通知——我们，主动地，让万物挠心。庄子的「静」，不是关掉手机——而是：建立一种内在的稳定——使得万物，无足以挠心——手机，在那里；通知，来了——但心，不被挠动——这，才是真正的静。但这种静，需要根基：「虚静恬淡寂漠无为——万物之本」——这个根基，不是一天建立的——它，需要：每天的「休」——每天的「虚」——每天的「不积」——慢慢地，建立起来。</p></blockquote><p><strong>思考二·「一心定」与现代焦虑</strong></p><blockquote><p>《天道》反复出现「一心定」——「一心定而王天下；一心定而万物服。」今天，「一心定」，是最稀缺的东西。现代人的焦虑，来自哪里？对未来的不确定（心不定）、对他人评价的在意（心不定）、对自我身份的困惑（心不定）、对选择的纠结（心不定）、对失去的恐惧（心不定）。每一种焦虑，都是「积」——都是心，停留在某个地方，无法流动。「一心定」，不是没有这些——而是：有这些，但心，不被这些所定义——心，有根基——这个根基，是「虚静恬淡寂漠无为」——有了这个根基，心，自然定。至人之心有所定——不是因为外在的一切都安定了——而是：通乎道·合乎德·退仁义·宾礼乐——内在的根基，建立了——心，自然定。</p></blockquote><p><strong>思考三·「形色名声」与信息时代的认识困境</strong></p><blockquote><p>「悲夫！世人以形色名声为足以得彼之情。」今天，这句话，比庄子时代，更加深刻——今天，我们拥有的「形色名声」，比任何时代都多：高清图像·环绕声音·大数据·算法分析——我们，以为这些，足以让我们了解一切——但庄子说：形色名声，不足以得彼之情。「彼之情」——那个东西（道）的实情——道，不在形色名声中。今天的「彼之情」，可以是：一个人的真实内心、一件事的真正本质、一个时代的深层逻辑——这些，都无法通过形色名声来得到——无论你有多少数据，多少图像，多少声音——「彼之情」，永远在这些之外。「知者不言，言者不知」——在信息爆炸的时代，这句话，更加深刻：说得最多的，往往不是最知道的——最知道的，往往沉默——因为：真正知道的，知道语言无法传递——所以，沉默。</p></blockquote><p><strong>思考四·「轮扁斫轮」与现代教育</strong></p><blockquote><p>轮扁斫轮，对今天的教育，有极深的启示：今天的教育，高度依赖「书·语·意」——课本·讲解·考试——这些，都是「书·语·意」的层面——但「意之所随」——那个真正的道——无法通过课本·讲解·考试来传递。轮扁说：「不徐不疾，得之于手而应于心，口不能言，有数存乎其间。」这个「数」，只能在做中得到——不能在听课中得到——不能在读书中得到——只能在：做。今天最好的教育，知道这一点：项目制学习·实习·导师制·做中学——这些，都是在寻找那个「有数存乎其间」——都是在寻找「得之于手而应于心」的体验。但今天的教育体系，仍然高度依赖「书·语·意」——仍然以为：考试考好了，就学到了——轮扁会说：「然则君之所学者，古人之糟粕已夫！」</p></blockquote><p><strong>思考五·「美则美矣·而未大也」——善意的局限</strong></p><blockquote><p>尧舜问答，给了今天一个极为重要的启示：尧的用心——不敖无告·不废穷民·苦死者·嘉孺子哀妇人——这些，都是好的——都是善意的——但舜说：美则美矣，而未大也。今天，很多「善意」，也停留在「美」的层面——没有到达「大」的层面：慈善·捐款（美，但未大——治标，不治本）；环保·减排（美，但未大——末节，不是根本）；教育·培训（美，但未大——知识，不是道）；心理咨询·自我成长（美，但未大——仍在「人之合」的层面）。「大」，是什么？是：天德而出宁——是：从天道出发，自然流出——不是刻意的善意，而是：本然的德性。这，不是说慈善·环保·教育没有价值——而是：这些，是末节——真正的根本，是：每个人，回到自己的本性——「放德而行，遁遁而趋，已至矣！」</p></blockquote><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>出处</th><th>核心含义</th></tr></thead><tbody><tr><td>运而无所积</td><td>第1段</td><td>《天道》最核心的概念。运行而不积滞，不执着于任何地方。天道·帝道·圣道，共同的特征</td></tr><tr><td>圣人之静·万物无足以挠心</td><td>第1段</td><td>圣人的静，不是主动追求的静，而是：万物无足以挠心，故静。区别于「非曰静也善，故静也」</td></tr><tr><td>天地之鉴·万物之镜</td><td>第1段</td><td>圣人之心静，是天地的镜子，万物的镜子。水静则明烛须眉——静心，才能映照一切</td></tr><tr><td>虚静恬淡寂漠无为·万物之本</td><td>第1段</td><td>五个并列：虚·静·恬淡·寂漠·无为。天地之平·道德之至·万物之本</td></tr><tr><td>休则虚·虚则实·实则伦</td><td>第1段</td><td>休→虚→实→伦。虚空，反而充实——虚，才能容纳</td></tr><tr><td>静而圣·动而王·无为而尊·朴素争美</td><td>第1段</td><td>第1段最精炼的总结。朴素，是最高的美，天下莫能与之争</td></tr><tr><td>天乐·吾师乎·四个不为</td><td>第1段</td><td>庄子称道为「吾师」。四个不为：赍万物不为戾·泽万世不为仁·长上古不为寿·刻雕众形不为巧</td></tr><tr><td>一心定而王天下·万物服</td><td>第1段</td><td>天乐的最精炼表达。不是靠武力或权谋，而是：一心安定，天下自然归王</td></tr><tr><td>无为则用天下而有余·有为则为天下用而不足</td><td>第2段</td><td>《天道》政治哲学最重要的命题。用天下（主动驾驭）vs 为天下用（被动驱使）</td></tr><tr><td>上必无为而用下·下必有为为天下用·不易之道</td><td>第2段</td><td>政治结构的不可改变的道理。上无为·下有为，是天地的秩序</td></tr><tr><td>五末·须精神之运·心术之动·然后从之</td><td>第3段</td><td>五个领域的末节：三军（德末）·赏罚（教末）·礼法（治末）·钟鼓（乐末）·哭泣（哀末）</td></tr><tr><td>语道而非其序者，非其道也</td><td>第3段</td><td>谈论道却违背其秩序，就不是道了</td></tr><tr><td>骤而语形名赏罚·辩士·一曲之人</td><td>第4段</td><td>跳过前面层级，直接谈形名赏罚——不知其本。有知治之具，非知治之道</td></tr><tr><td>礼法形名：下之所以事上·非上之所以畜下</td><td>第4段</td><td>礼法形名，是下位者的工具，不是上位者的工具</td></tr><tr><td>美则美矣·而未大也·人之合·天之合</td><td>第5段</td><td>尧舜问答的核心。尧：人之合（停留在人道层面）；舜：天之合（天道自然流出）</td></tr><tr><td>天德而出宁·云行而雨施</td><td>第5段</td><td>舜描绘「大」的状态。天德自然流出安宁，云自然运行，雨自然降施</td></tr><tr><td>古之王天下者，奚为哉？天地而已矣</td><td>第5段</td><td>王天下，只需效法天地。天地：运而无所积，虚静无为</td></tr><tr><td>兼爱迂·无私乃私·放德而行·已至矣</td><td>第6段</td><td>老聃批判孔子仁义论的核心。兼爱是刻意的，迂腐；无私，执着于无私，反而是私。正面：放德而行，遁遁而趋，已至矣</td></tr><tr><td>若击鼓而求亡子·乱人之性</td><td>第6段</td><td>标榜仁义，像敲鼓找逃跑的孩子——适得其反。结果：乱人之性</td></tr><tr><td>呼我牛谓之牛·呼我马谓之马·吾服也恒服</td><td>第7段</td><td>老子的自我描述。接受名字，但不被名字所定义。本然的顺服，不是有为的顺服</td></tr><tr><td>边竟有人焉·其名为窃</td><td>第7段</td><td>老子对士成绮的最终判断。停留在边界上，用「窃」的方式求道</td></tr><tr><td>形德仁义·神之末也·非至人孰能定之</td><td>第8段</td><td>形·德·仁义，都是精神（神）的末节。至人从精神（本）出发</td></tr><tr><td>外天地·遗万物·神未尝有所困</td><td>第8段</td><td>至人的处世方式。与《天地》「忘乎物·忘乎天·忘己·入于天」呼应</td></tr><tr><td>通乎道·合乎德·退仁义·宾礼乐·至人之心有所定</td><td>第8段</td><td>至人修道的四个层次，对应九层序列的个人版本</td></tr><tr><td>书·语·意·意之所随·不可以言传</td><td>第9段</td><td>认识论的四层递进。书→语→意→意之所随（道）。每一层都无法完全传递上一层</td></tr><tr><td>知者不言·言者不知</td><td>第9段</td><td>《天道》最著名的一句话。与《老子》「知者不博，博者不知」呼应</td></tr><tr><td>不徐不疾·得之于手而应于心·有数存乎其间</td><td>第10段</td><td>轮扁斫轮的核心。道，在做的过程中，在手与心的感应中，无法用语言传递</td></tr><tr><td>古之人与其不可传也死矣·古人之糟粕已夫</td><td>第10段</td><td>轮扁斫轮的结论。书，是糟粕；道，在书之外，在做的过程中</td></tr></tbody></table><h3 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h3><p>如果《天道》全篇，只能用一句话来总结——</p><blockquote><p><strong>「虚静恬淡寂漠无为者，万物之本也。」</strong></p></blockquote><p>如果只能用一个问题来收束——</p><blockquote><p><strong>你，在「积」什么？你，在哪里停留，无法流动？</strong></p></blockquote><p>如果只能用一个意象来记住《天道》——</p><blockquote><p><strong>轮扁，七十岁，还在斫轮——他，有那个「数」——但他，无法传给儿子——他，只能自己做到死——这，不是悲剧——这，是道的本质：道，只能自己体会——无法被传递——无法被继承——只能，在你自己的「斫轮」中，慢慢地，找到那个「不徐不疾」。</strong></p></blockquote><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>《庄子·外篇·天道》</li></ul>`,40))])}}});export{I as __pageData,B as default};
